  # A graph under construction. Its builders (`matmul`, `conv2d`, …) are the op
  # table's (`table.rs`); these rows are its lifecycle.
  class Graph < Handle
    FREE = :rlx_graph_free

    def initialize(name: "graph")
      a_name = RLX.cstr(name)
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_graph_new, a_name, o0))
