      RLX.check_rc(RLX.call(:rlx_graph_clone, @handle, o0))
      Graph.wrap(RLX.ptr_at(o0))
    end

    # Whether a compile (or a body-graph argument) consumed it.
    def is_consumed()
      RLX.call(:rlx_graph_is_consumed, @handle)
    end

    # A runtime input. `dtype` defaults to f32.
    def input(name, shape, dtype: "f32")
      a_name = RLX.cstr(name)
      a_shape = RLX.buf("J", shape)
      a_dtype = RLX.cstr(dtype)
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_input, @handle, a_name, a_shape, shape.size, a_dtype, o0))
      o0[0, 4].unpack1("L")
    end

    # A trainable / loadable weight, filled by `set_params` at run time.
    def param(name, shape, dtype: "f32")
      a_name = RLX.cstr(name)
      a_shape = RLX.buf("J", shape)
      a_dtype = RLX.cstr(dtype)
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_param, @handle, a_name, a_shape, shape.size, a_dtype, o0))
      o0[0, 4].unpack1("L")
    end

    # A rank-0 literal that broadcasts in binary ops.
    def constant(value, dtype: "f32")
      a_dtype = RLX.cstr(dtype)
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_constant, @handle, value.to_f, a_dtype, o0))
      o0[0, 4].unpack1("L")
    end

    # A constant tensor of zeros.
