      a_dims = RLX.buf("J", dims)
      a_dtype = RLX.cstr(dtype)
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_zeros, @handle, a_dims, dims.size, a_dtype, o0))
      o0[0, 4].unpack1("L")
    end

    # A constant tensor filled with `value`.
