      a_dims = RLX.buf("J", dims)
      a_dtype = RLX.cstr(dtype)
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_full, @handle, a_dims, dims.size, value.to_f, a_dtype, o0))
      o0[0, 4].unpack1("L")
    end

