    def batched_dense_solve(a, b, out_shape: nil, dtype: "f32")
      a_out_shape = out_shape.nil? ? nil : RLX.buf("J", out_shape)
      a_dtype = RLX.cstr(dtype)
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_batched_dense_solve, @handle, a, b, a_out_shape, (out_shape.nil? ? 0 : out_shape.size), a_dtype, o0))
