    # Batched symmetric eigendecomposition → `(eigenvalues, eigenvectors)`.
    def eigh_batch(a)
      o0 = RLX.out(4)
      o1 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_eigh_batch, @handle, a, o0, o1))
      { first: o0[0, 4].unpack1("L"), second: o1[0, 4].unpack1("L") }
    end

    # One factor of the thin QR of `a [m, n]`: `Q [m, k]` or `R [k, n]`.
    def qr(a, part: "q")
      a_part = RLX.cstr(part)
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_qr, @handle, a, a_part, o0))
