      RLX.check_rc(RLX.call(:rlx_graph_custom_fn_multi, @handle, a_inputs, inputs.size, fwd_body.handle, o0))
      RLX.take_array(o0, "L", 4, :rlx_u32s_release)
    end

    # An op registered through `rlx_ir::register_op`. `attrs` is its
    # serialized attribute bytes; `out_shape` declares a packed output.
    def custom_op(name, inputs, attrs: [], out_shape: nil, dtype: "f32")
      a_name = RLX.cstr(name)
      a_inputs = RLX.buf("L", inputs)
      a_attrs = RLX.buf("C", attrs)
      a_out_shape = out_shape.nil? ? nil : RLX.buf("J", out_shape)
      a_dtype = RLX.cstr(dtype)
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_graph_custom_op, @handle, a_name, a_inputs, inputs.size, a_attrs, attrs.size, a_out_shape, (out_shape.nil? ? 0 : out_shape.size), a_dtype, o0))
      o0[0, 4].unpack1("L")
    end

