  # A graph split into self-contained parts that run in order: part i reads
  # its `imports` from earlier parts' `exports` of the same name.
  class Partition < Handle
    FREE = :rlx_partition_free

    # Node i goes to part assign[i] (`node_count()` entries; inputs', params'
    # and constants' are ignored). Every edge must run to the same or a later part.
    def initialize(graph, assign)
      a_assign = RLX.buf("L", assign)
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_new, graph.handle, a_assign, assign.size, o0))
      adopt(RLX.ptr_at(o0))
    end

    # Two parts: `cut` and everything it reads, then the rest.
    def self.split_at(graph, cut)
      a_cut = RLX.buf("L", cut)
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_split_at, graph.handle, a_cut, cut.size, o0))
      Partition.wrap(RLX.ptr_at(o0))
    end

    # One part per independent subgraph; the parts import nothing.
    def self.components(graph)
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_components, graph.handle, o0))
      Partition.wrap(RLX.ptr_at(o0))
    end

    # The number of parts.
    def num_parts()
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_num_parts, @handle, o0))
      o0[0, 8].unpack1("J")
    end

    # A copy of one part's graph.
    def graph(part)
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_graph, @handle, part, o0))
      Graph.wrap(RLX.ptr_at(o0))
    end

    # The boundary names a part reads.
    def imports(part)
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_imports, @handle, part, o0))
      JSON.parse(RLX.take_string(o0))
    end

    # The name of each of a part's outputs.
    def exports(part)
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_exports, @handle, part, o0))
      JSON.parse(RLX.take_string(o0))
    end

    # Where each source output went: [[part, output index], …].
    def outputs()
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_outputs, @handle, o0))
      JSON.parse(RLX.take_string(o0))
    end

    # The parts as one graph again.
    def merge()
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_partition_merge, @handle, o0))
      Graph.wrap(RLX.ptr_at(o0))
    end

  end

  # A device and precision to compile graphs for.
  class Session < Handle
    FREE = :rlx_session_free

    # `policy` is a preset name ("mixed") or {op kind: dtype}.
    def initialize(device: "cpu", precision: "f32", policy: nil)
      a_device = RLX.cstr(device)
      a_precision = RLX.cstr(precision)
      a_policy = policy.nil? ? nil : RLX.cstr(JSON.generate(policy))
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_session_new, a_device, a_precision, a_policy, o0))
      adopt(RLX.ptr_at(o0))
    end

    # The device label.
    def device()
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_session_device, @handle, o0))
      RLX.take_string(o0)
    end

    # "f32", "f16" or "bf16".
    def precision()
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_session_precision, @handle, o0))
      RLX.take_string(o0)
    end

    # The precision policy's label, if any.
    def policy()
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_session_policy, @handle, o0))
      RLX.take_string_or_nil(o0)
    end

    # Compile `graph` (consumed). options: {fusion, kernel_dispatch, policy}.
    def compile(graph, options: nil)
      a_options = options.nil? ? nil : RLX.cstr(JSON.generate(options))
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_session_compile, @handle, graph.handle, a_options, o0))
      Compiled.wrap(RLX.ptr_at(o0))
