  # This process's place in a mesh of rlx nodes: point-to-point messages,
  # collectives, and the ship-graph protocol (a coordinator ships a stage or a
  # training job; generic workers run it on their own hardware).
  class Group < Handle
    FREE = :rlx_group_free

    private_class_method :new

    # Join a mesh as `rank` of `world`. options: {peers: ["host:port", …],
    # topology: "mesh" | "star", device: "auto", discover: {port, data_port,
    # via}, heap_mb}. Blocks until every peer connects.
    def self.connect(rank, world, options: nil)
      a_options = options.nil? ? nil : RLX.cstr(JSON.generate(options))
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_group_connect, rank, world, a_options, o0))
      Group.wrap(RLX.ptr_at(o0))
    end

    # Join with RANK / WORLD / PEERS / TOPOLOGY / DEVICE / DISCOVER from the environment.
    def self.from_env()
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_group_from_env, o0))
      Group.wrap(RLX.ptr_at(o0))
    end

    # This node's rank.
    def rank()
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_group_rank, @handle, o0))
      o0[0, 4].unpack1("L")
    end

    # Ranks in the mesh.
    def world()
      o0 = RLX.out(4)
      RLX.check_rc(RLX.call(:rlx_group_world, @handle, o0))
      o0[0, 4].unpack1("L")
    end

    # Whether this is rank 0.
    def is_leader()
      o0 = RLX.out(1)
      RLX.check_rc(RLX.call(:rlx_group_is_leader, @handle, o0))
      (o0[0, 1].unpack1("C") != 0)
    end

    # Wait until every rank arrives.
    def barrier()
      RLX.check_rc(RLX.call(:rlx_group_barrier, @handle))
      nil
    end

    # Send f32 values to rank `to` under `tag`.
    def send_to(to, tag, data)
      a_data = RLX.buf("f", data)
      RLX.check_rc(RLX.call(:rlx_group_send, @handle, to, tag, a_data, data.size))
      nil
    end

    # Receive f32 values from rank `from` under `tag`.
    def recv(from, tag)
      o0 = RLX.out(16)
      RLX.check_rc(RLX.call(:rlx_group_recv, @handle, from, tag, o0))
      RLX.take_array(o0, "f", 4, :rlx_f32s_release)
    end

    # Reduce across every rank: op "sum" | "mean" | "max" | "min".
    def all_reduce(data, op: "sum")
      a_data = RLX.buf("f", data)
      a_op = RLX.cstr(op)
      o0 = RLX.out(16)
      RLX.check_rc(RLX.call(:rlx_group_all_reduce, @handle, a_data, data.size, a_op, o0))
      RLX.take_array(o0, "f", 4, :rlx_f32s_release)
    end

    # Every rank's values, concatenated in rank order.
    def all_gather(data)
      a_data = RLX.buf("f", data)
      o0 = RLX.out(16)
      RLX.check_rc(RLX.call(:rlx_group_all_gather, @handle, a_data, data.size, o0))
      RLX.take_array(o0, "f", 4, :rlx_f32s_release)
    end

    # Rank `root`'s values, on every rank; other ranks pass a buffer of the root's length.
    def broadcast(root, data)
      a_data = RLX.buf("f", data)
      o0 = RLX.out(16)
      RLX.check_rc(RLX.call(:rlx_group_broadcast, @handle, root, a_data, data.size, o0))
      RLX.take_array(o0, "f", 4, :rlx_f32s_release)
    end

    # Coordinator: the capabilities each worker announced, [{rank, devices, platform, role}].
    def collect_caps()
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_group_collect_caps, @handle, o0))
      JSON.parse(RLX.take_string(o0))
    end

    # Coordinator: ship a stage of `graph` to worker `rank`. options: {input,
    # output, device, weights: {param: uri}, packed: {param: uri}, stage_id}.
    def ship_stage(rank, graph, options)
      a_options = RLX.cstr(JSON.generate(options))
      RLX.check_rc(RLX.call(:rlx_group_ship_stage, @handle, rank, graph.handle, a_options))
      nil
    end

    # Send an activation to rank `to`.
    def send_activation(to, data)
      a_data = RLX.buf("f", data)
      RLX.check_rc(RLX.call(:rlx_group_send_activation, @handle, to, a_data, data.size))
      nil
    end

    # Receive an activation from rank `from`.
    def recv_activation(from)
      o0 = RLX.out(16)
      RLX.check_rc(RLX.call(:rlx_group_recv_activation, @handle, from, o0))
      RLX.take_array(o0, "f", 4, :rlx_f32s_release)
    end

    # Worker: announce, receive a stage, serve activations until the
    # coordinator finishes (or `steps`). options: {steps}. Returns {rank, device, platform, activations}.
    def serve_worker(options: nil)
      a_options = options.nil? ? nil : RLX.cstr(JSON.generate(options))
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_group_serve_worker, @handle, a_options, o0))
      JSON.parse(RLX.take_string(o0))
    end

    # Coordinator: ship a data-parallel training job for backward `graph` to
    # worker `rank`. spec: {params: [{name, uri}], data: [{input, uri, elem,
    # shard_start, shard_len}], grad_start, loss_index, seed_input, momentum,
    # lr_per_epoch, batch, device, push_data}.
    def ship_train(rank, graph, spec)
      a_spec = RLX.cstr(JSON.generate(spec))
      RLX.check_rc(RLX.call(:rlx_group_ship_train, @handle, rank, graph.handle, a_spec))
      nil
    end

    # Train this rank's shard of a job in lockstep with the workers; returns
    # {metrics, params}.
    def run_train(graph, spec)
      a_spec = RLX.cstr(JSON.generate(spec))
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_group_run_train, @handle, graph.handle, a_spec, o0))
      JSON.parse(RLX.take_string(o0))
    end

    # Worker: announce, receive a training job, train in lockstep; returns {rank, platform, metrics, params}.
    def serve_trainer(options: nil)
      a_options = options.nil? ? nil : RLX.cstr(JSON.generate(options))
      o0 = RLX.out(8)
      RLX.check_rc(RLX.call(:rlx_group_serve_trainer, @handle, a_options, o0))
      JSON.parse(RLX.take_string(o0))
    end

  end

